content.text:
{
  "name": "三路直流电源",
  "name_en": "Triple-Output DC Power Supply",
  "manufacturer": "HP",
  "description": "HP E3631A 是一款实验室台式三路可编程直流电源，提供 +6 V/5 A、+25 V/1 A 和 -25 V/1 A 三个输出通道。它用于为电子电路、原型系统和实验装置提供稳定的直流电压或电流，并支持恒压/恒流工作方式。",
  "description_en": "The HP E3631A is a bench-top triple-output programmable DC power supply with +6 V/5 A, +25 V/1 A, and -25 V/1 A outputs. It is used in laboratories to provide stable DC voltage or current for electronic circuits, prototypes, and experimental setups, with automatic constant-voltage and constant-current operation.",
  "actions": [
    {
      "action_name": "auto-channelid",
      "description": "获取/设置当前选中的输出通道编号",
      "description_en": "get/set the currently selected output channel ID"
    },
    {
      "action_name": "auto-current",
      "description": "获取/设置输出电流设定值",
      "description_en": "get/set the output current setting"
    },
    {
      "action_name": "auto-output",
      "description": "获取/设置电源输出开关状态",
      "description_en": "get/set the power output on/off state"
    },
    {
      "action_name": "auto-voltage",
      "description": "获取/设置输出电压",
      "description_en": "get/set the output voltage"
    },
    {
      "action_name": "auto-channel",
      "description": "获取指定输出通道",
      "description_en": "get the specified output channel"
    },
    {
      "action_name": "auto-mode",
      "description": "获取工作模式",
      "description_en": "get the operating mode"
    },
    {
      "action_name": "auto-voltage_min",
      "description": "获取当前通道的最小电压",
      "description_en": "get the minimum voltage for the current channel"
    },
    {
      "action_name": "auto-voltage_max",
      "description": "获取当前通道的最大电压",
      "description_en": "get the maximum voltage for the current channel"
    },
    {
      "action_name": "auto-voltage_range",
      "description": "获取当前通道的电压范围",
      "description_en": "get the voltage range for the current channel"
    }
  ],
  "tag_hints": [
    "triple-output DC power supply",
    "bench power supply",
    "programmable voltage/current",
    "constant-voltage mode",
    "constant-current mode",
    "electronics testing",
    "dual-polarity supply"
  ]
}

